// withFixedClock pins the package clock `now` to fixed for the test and restores
// the production clock on cleanup (deterministic expiresAt; hermeticity). Mid-
// test clock advancement reassigns `now` directly — cleanup still restores the
// original.
func withFixedClock(t *testing.T, fixed time.Time) {
	t.Helper()
	realNow := now
	now = func() time.Time { return fixed }
	t.Cleanup(func() { now = realNow })
}

// TestLeaseMap covers the S4 (lease half) joint: acquire mutual-exclusion, lazy
// expiry reclaim, the expired probe, idempotent release, and renew. All times
// are deterministic via the package clock.
func TestLeaseMap(t *testing.T) {
	t0 := time.Date(2026, 8, 3, 12, 0, 0, 0, time.UTC)

	t.Run("acquire_when_free_then_live_blocks", func(t *testing.T) {
		withFixedClock(t, t0)
		m := newLeaseMap()
		if !m.acquire("i1", "w1", time.Second) {
			t.Fatal("first acquire(i1) = false, want true (free)")
		}
		if m.acquire("i1", "w2", time.Second) {
			t.Fatal("second acquire(i1) = true, want false (a live lease blocks any other acquire)")
		}
	})

	t.Run("acquire_after_expiry_lazy_reclaim", func(t *testing.T) {
		withFixedClock(t, t0)
		m := newLeaseMap()
		if !m.acquire("i1", "w1", time.Second) { // expiresAt = t0+1s
			t.Fatal("acquire at t0 = false, want true")
		}
		now = func() time.Time { return t0.Add(2 * time.Second) } // advance past expiry
		if !m.acquire("i1", "w2", time.Second) {
			t.Fatal("acquire after expiry = false, want true (lazy reclaim of the dead lease)")
		}
	})

	t.Run("expired_probe_boundary", func(t *testing.T) {
		withFixedClock(t, t0)
		m := newLeaseMap()
		if !m.expired("missing", t0) { // no lease -> expired
			t.Fatal("expired(missing) = false, want true")
		}
		m.acquire("i1", "w1", time.Second) // expiresAt = t0+1s
		if m.expired("i1", t0) {           // live (now < expiry)
			t.Fatal("expired(i1, t0) = true, want false (lease is live)")
		}
		if !m.expired("i1", t0.Add(time.Second)) { // at/before now boundary
			t.Fatal("expired(i1, t0+1s) = false, want true (expiresAt at/before now)")
		}
		if !m.expired("i1", t0.Add(2*time.Second)) { // past
			t.Fatal("expired(i1, t0+2s) = false, want true (past expiry)")
		}
	})

	t.Run("release_then_reacquire_idempotent", func(t *testing.T) {
		withFixedClock(t, t0)
		m := newLeaseMap()
		m.acquire("i1", "w1", time.Second)
		m.release("i1")
		if !m.acquire("i1", "w2", time.Second) { // explicit release freed it
			t.Fatal("acquire after release = false, want true")
		}
		m.release("nope") // idempotent: absent lease does not panic
	})

	t.Run("renew_extends_live_else_false", func(t *testing.T) {
		withFixedClock(t, t0)
		m := newLeaseMap()
		if m.renew("absent", time.Second) {
			t.Fatal("renew(absent) = true, want false")
		}
		m.acquire("i1", "w1", time.Second)                               // expiresAt = t0+1s
		now = func() time.Time { return t0.Add(500 * time.Millisecond) } // still live
		if !m.renew("i1", time.Second) {
			t.Fatal("renew(live) = false, want true")
		}
		// renew reset expiresAt to (t0+500ms)+1s = t0+1500ms.
		if m.expired("i1", t0.Add(time.Second)) { // t0+1s < new deadline -> still live
			t.Fatal("expired(i1, t0+1s) after renew = true, want false (renew extended the lease)")
		}
		if !m.expired("i1", t0.Add(1500*time.Millisecond)) { // at the new deadline
			t.Fatal("expired(i1, t0+1500ms) after renew = false, want true (new expiresAt)")
		}
	})
}

// TestLeaseMap_ConcurrentAcquire is the AC-lease mutual-exclusion unit: N
// goroutines race to acquire the SAME item; exactly one wins
// (INV-one-lease-per-item). Owners are identical because acquire is
// owner-agnostic (INV-owner-is-logical) — the assertion is about the mutex, not
// owner comparison. Run under -race (refactoring_checklist).
func TestLeaseMap_ConcurrentAcquire(t *testing.T) {
	withFixedClock(t, time.Date(2026, 8, 3, 12, 0, 0, 0, time.UTC))
	m := newLeaseMap()
	const N = 10
	var winners int64
	var wg sync.WaitGroup
	start := make(chan struct{})
	wg.Add(N)
	for i := 0; i < N; i++ {
		go func() {
			defer wg.Done()
			<-start
			if m.acquire("shared", "w", time.Minute) { // ttl >> test runtime; never expires mid-race
				atomic.AddInt64(&winners, 1)
			}
		}()
	}
	close(start) // release all goroutines onto the mutex simultaneously
	wg.Wait()
	if winners != 1 {
		t.Fatalf("concurrent acquire winners = %d, want exactly 1 (serialize-within-item)", winners)
	}
}
